#!/usr/bin/env bash

tmp=''
work=''
step=init
output=''

main() {
  set -Eeuo pipefail
  [[ "${THOIDAI_ATTENDANCE_DRYRUN_APPROVED:-0}" == 1 ]] || { echo 'ATTENDANCE_DRYRUN_ERROR=approval required' >&2; return 1; }
  : "${BUNDLE_DIR:?BUNDLE_DIR is required}"; : "${POSTGRES_IMAGE:?POSTGRES_IMAGE is required}"
  command -v docker >/dev/null; command -v node >/dev/null
  local evidence="/opt/ops/thoidai-work/attendance-evidence/dryrun-$(date -u +%Y%m%dT%H%M%SZ)" daily=/opt/ops/thoidai-work/backups/managed/daily
  tmp="attendance-dryrun-$$"; work=''; output=''
  local backup='' dump='' manifest='' db_password='' port='' apply_out='' pass_count='' fail_count=''
  local expected_pass=26
  output="$evidence/behaviour.txt"; mkdir -p "$evidence"
  cleanup() { local rc=$?; set +u; set +e; if [[ $rc -ne 0 ]]; then echo "ATTENDANCE_DRYRUN_RESULT=FAIL step=$step" >&2; [[ -f "$output" ]] && tail -n 20 "$output" >&2; fi; [[ -n "$tmp" ]] && docker rm -f -v "$tmp" >/dev/null 2>&1; [[ -n "$work" ]] && rm -rf -- "$work"; return "$rc"; }; trap cleanup EXIT
  step=disk; "$BUNDLE_DIR/scripts/production/disk-guard.sh"; work=$(mktemp -d)
  step=backup; while IFS= read -r entry; do [[ -f "$daily/$entry/postgres.dump" && -f "$daily/$entry/manifest.txt" ]] && { backup="$daily/$entry"; break; }; done < <(find "$daily" -mindepth 1 -maxdepth 1 -type d -name '*-daily' -printf '%f\n' | sort -r)
  [[ -n "$backup" ]]; dump="$backup/postgres.dump"; manifest="$backup/manifest.txt"; [[ "$(awk '$2=="postgres.dump" || $2=="*postgres.dump" {print $1; exit}' "$manifest")" == "$(sha256sum "$dump" | awk '{print $1}')" ]]
  step=postgres; if docker ps -a --format '{{.Names}}' | grep -Eq '^attendance-dryrun-[^[:space:]]+$'; then echo 'ATTENDANCE_DRYRUN_ERROR=leftover dry-run container exists' >&2; return 1; fi
  db_password=$(od -An -N24 -tx1 /dev/urandom | tr -d ' \n'); docker run -d --name "$tmp" --memory 512m -p 127.0.0.1::5432 -e POSTGRES_PASSWORD="$db_password" "$POSTGRES_IMAGE" >/dev/null
  for _ in $(seq 1 90); do docker exec "$tmp" pg_isready -h 127.0.0.1 -U supabase_admin -d postgres >/dev/null 2>&1 && break; sleep 2; done
  docker exec -i "$tmp" psql -q -h 127.0.0.1 -U supabase_admin -d postgres -v ON_ERROR_STOP=1 -c 'create schema if not exists supabase_migrations;' </dev/null >/dev/null
  docker exec -i "$tmp" pg_restore --schema=public --schema=supabase_migrations -h 127.0.0.1 -U supabase_admin -d postgres < "$dump" >"$work/restore.log" 2>&1 || true
  port=$(docker port "$tmp" 5432/tcp | sed -n 's/.*127.0.0.1:\([0-9]*\).*/\1/p' | head -n1); [[ "$port" =~ ^[0-9]+$ ]]
  export ATTENDANCE_DB_URL="postgresql://supabase_admin:$db_password@127.0.0.1:$port/postgres" SAFE_MIGRATION_MIGRATIONS_DIR="$BUNDLE_DIR/supabase/migrations"
  step=apply_rbac; apply_out=$(MIGRATION_EVIDENCE_DIR="$evidence" "$BUNDLE_DIR/scripts/production/safe-apply-migration.sh" --file "$BUNDLE_DIR/supabase/migrations/20261028100000_rbac_approval_permissions_v1.sql" --db-url-env ATTENDANCE_DB_URL --postcondition-sql "$BUNDLE_DIR/scripts/production/rbac-approval/post/20261028100000_rbac_approval_permissions_v1.sql" --evidence-dir "$evidence"); echo "$apply_out"; grep -q '^PASS' <<<"$apply_out"
  psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.proname,md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname in ('rbac_v2_scope_supported','api_upsert_attendance_admin_note') or p.proname like '%late_exception%' or p.proname like '%workday_adjustment%') order by p.proname,p.oid" > "$evidence/post-rbac-md5.txt"
  psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select code,name,coalesce(description,'') from public.permissions where code like 'attendance.%' order by code" > "$evidence/post-rbac-permissions.txt"
  psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.code,g.scope from public.role_permission_grants g join public.permissions p on p.id=g.permission_id where p.code like 'attendance.%' order by p.code,g.scope" > "$evidence/post-rbac-role-grants.txt"
  step=apply; for file in 20261028120000_attendance_rbac_v1.sql 20261028130000_attendance_late_exception_review.sql 20261028140000_attendance_workday_adjustments.sql; do apply_out=$(MIGRATION_EVIDENCE_DIR="$evidence" "$BUNDLE_DIR/scripts/production/safe-apply-migration.sh" --file "$BUNDLE_DIR/supabase/migrations/$file" --db-url-env ATTENDANCE_DB_URL --evidence-dir "$evidence"); echo "$apply_out"; grep -q '^PASS' <<<"$apply_out"; done
  step=backfill_check; local exempt_count; exempt_count=$(psql -q "$ATTENDANCE_DB_URL" -At -c 'select count(*) from public.staff_users where attendance_exempt'); echo "ATTENDANCE_EXEMPT_COUNT=$exempt_count"; [[ "$exempt_count" == 3 ]]
  step=lockdown; [[ "$(psql -q "$ATTENDANCE_DB_URL" -At -c "select count(*) from information_schema.role_table_grants where table_schema='public' and table_name='attendance_workday_adjustments' and grantee in ('anon','authenticated') and privilege_type <> ''")" == 0 ]]; [[ "$(psql -q "$ATTENDANCE_DB_URL" -At -c "select count(*) from (values ('api_request_late_exception(uuid,date,text)'),('api_review_late_exception(uuid,uuid,text,text)'),('api_list_reviewable_late_exceptions(uuid,date,date)'),('api_upsert_attendance_admin_note(uuid,uuid,date,text)'),('api_upsert_attendance_workday_adjustment(uuid,uuid,date,numeric,text)'),('api_delete_attendance_workday_adjustment(uuid,uuid,date)')) f(sig) where has_function_privilege('anon', 'public.'||sig, 'execute') or has_function_privilege('authenticated', 'public.'||sig, 'execute') or has_function_privilege('public', 'public.'||sig, 'execute'))" )" == 0 ]]; [[ "$(psql -q "$ATTENDANCE_DB_URL" -At -c "select count(*) from pg_class where oid='public.attendance_workday_adjustments'::regclass and relrowsecurity")" == 1 ]]
  step=behaviour; psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/supabase/tests/attendance_v1_behaviour.sql" >"$output" 2>&1; pass_count=$(grep -c 'NOTICE:  ATT_TEST_PASS' "$output" || true); fail_count=$(grep -c 'ATT_TEST_FAIL' "$output" || true); [[ "$pass_count" == "$expected_pass" && "$fail_count" == 0 ]]
  step=rbac_behaviour; psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/supabase/tests/rbac_approval_v1_behaviour.sql" >"$evidence/rbac-behaviour.txt" 2>&1; local rbac_pass rbac_fail; rbac_pass=$(grep -c 'NOTICE:  RBAC_TEST_PASS' "$evidence/rbac-behaviour.txt" || true); rbac_fail=$(grep -c 'RBAC_TEST_FAIL' "$evidence/rbac-behaviour.txt" || true); [[ "$rbac_pass" == 21 && "$rbac_fail" == 0 ]]
  psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.proname,md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname in ('rbac_v2_scope_supported','api_upsert_attendance_admin_note') or p.proname like '%late_exception%' or p.proname like '%workday_adjustment%') order by p.proname,p.oid" > "$evidence/post-attendance-md5.txt"
  psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select code,name,coalesce(description,'') from public.permissions where code like 'attendance.%' order by code" > "$evidence/post-attendance-permissions.txt"
  psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.code,g.scope from public.role_permission_grants g join public.permissions p on p.id=g.permission_id where p.code like 'attendance.%' order by p.code,g.scope" > "$evidence/post-attendance-role-grants.txt"
  step=idempotency; for file in 20261028120000_attendance_rbac_v1.sql 20261028130000_attendance_late_exception_review.sql 20261028140000_attendance_workday_adjustments.sql; do psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/supabase/migrations/$file" >/dev/null; done
  psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.proname,md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname in ('rbac_v2_scope_supported','api_upsert_attendance_admin_note') or p.proname like '%late_exception%' or p.proname like '%workday_adjustment%') order by p.proname,p.oid" > "$work/idempotent-md5.txt"; cmp -s "$evidence/post-attendance-md5.txt" "$work/idempotent-md5.txt"; cmp -s "$evidence/post-attendance-permissions.txt" <(psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select code,name,coalesce(description,'') from public.permissions where code like 'attendance.%' order by code"); cmp -s "$evidence/post-attendance-role-grants.txt" <(psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.code,g.scope from public.role_permission_grants g join public.permissions p on p.id=g.permission_id where p.code like 'attendance.%' order by p.code,g.scope")
  step=revert; psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/scripts/production/attendance-workday-adjustments-revert.sql" >/dev/null; psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/scripts/production/attendance-late-exception-review-revert.sql" >/dev/null; psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/scripts/production/attendance-rbac-v1-revert.sql" >/dev/null
  psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -c "delete from supabase_migrations.schema_migrations where version in ('20261028120000','20261028130000','20261028140000')"; psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.proname,md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname in ('rbac_v2_scope_supported','api_upsert_attendance_admin_note') or p.proname like '%late_exception%' or p.proname like '%workday_adjustment%') order by p.proname,p.oid" > "$work/reverted-md5.txt"; diff -u "$evidence/post-rbac-md5.txt" "$work/reverted-md5.txt" >/dev/null; diff -u "$evidence/post-rbac-permissions.txt" <(psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select code,name,coalesce(description,'') from public.permissions where code like 'attendance.%' order by code") >/dev/null; diff -u "$evidence/post-rbac-role-grants.txt" <(psql -q "$ATTENDANCE_DB_URL" -At -F'|' -c "select p.code,g.scope from public.role_permission_grants g join public.permissions p on p.id=g.permission_id where p.code like 'attendance.%' order by p.code,g.scope") >/dev/null
  step=reapply; for file in 20261028120000_attendance_rbac_v1.sql 20261028130000_attendance_late_exception_review.sql 20261028140000_attendance_workday_adjustments.sql; do apply_out=$(MIGRATION_EVIDENCE_DIR="$evidence" "$BUNDLE_DIR/scripts/production/safe-apply-migration.sh" --file "$BUNDLE_DIR/supabase/migrations/$file" --db-url-env ATTENDANCE_DB_URL --evidence-dir "$evidence"); echo "$apply_out"; grep -q '^PASS' <<<"$apply_out"; done; psql -q "$ATTENDANCE_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/supabase/tests/attendance_v1_behaviour.sql" >"$evidence/reapply-behaviour.txt" 2>&1; [[ "$(grep -c 'NOTICE:  ATT_TEST_PASS' "$evidence/reapply-behaviour.txt" || true)" == "$expected_pass" ]]; [[ "$(grep -c 'ATT_TEST_FAIL' "$evidence/reapply-behaviour.txt" || true)" == 0 ]]
  echo "ATTENDANCE_DRYRUN_RESULT=PASS evidence=$evidence"
}
main "$@" </dev/null
